export const designModes: readonly DesignModeDefinition[] = profiles.map(
    ([id, name, group, description, palette, tokens, colors], index) => ({
        id, name, group, description,
        atlasCaseId: index === 0 ? null : String(index).padStart(2, "0"),
        releaseStatus: id === "basic" ? "released" : "ready",
        appearances: ["dark-ui", "cyber", "terminal"].includes(id)
            ? ["dark"] : ["light", "dark"],
        defaultAppearance: ["dark-ui", "cyber", "terminal"].includes(id)
            ? "dark" : "light",
        colormaps: allPalettes,
        recipe: id === "bento" || id === "spatial" ? id : "standard",
        tokens,
        palettes: {
            light: { ...paletteTokens[palette].light, ...colors?.light },
            dark: { ...paletteTokens[palette].dark, ...colors?.dark },
        },
    }),
);

export function isDesignModeId(value: unknown): value is DesignModeId {
    return typeof value === "string"
        && designModeIds.some((id) => id === value);
}

export function getDesignMode(id: DesignModeId): DesignModeDefinition {
    return designModes.find((mode) => mode.id === id)!;
}

export const releasedDesignModes = designModes.filter(
    (mode) => mode.releaseStatus === "released",
);

// Metadata is shared by scopes and controllers; callers must not mutate it.
function freezeMetadata(value: object): void {
    Object.freeze(value);
    for (const child of Object.values(value)) {
        if (child && typeof child === "object" && !Object.isFrozen(child)) {
            freezeMetadata(child);
        }
    }
}
for (const value of [
    colorTokens, colormaps, paletteTokens, basicShapeTokens,
    basicDocumentTokens, designModeIds, designModes, releasedDesignModes,
]) freezeMetadata(value);

import {
    basicDocumentTokens, basicShapeTokens, colorTokens, colormaps,
    getDesignMode, isDesignModeId, paletteTokens,
    type Appearance, type ColorOverrides, type ColorToken,
    type PaletteId, type ThemeSettings, type ThemeTokenMap,
} from "./design-modes";

export type ThemeResolutionOptions = { allowUnreleased?: boolean };
export type ThemeResolution = { settings: ThemeSettings; issues: string[] };
export const defaultThemeSettings: ThemeSettings = Object.freeze({
    version: 1, design: "basic", appearance: "light", colormap: "neutral",
    overrides: Object.freeze({
        light: Object.freeze({}), dark: Object.freeze({}),
    }),
});
const appearances: Appearance[] = ["light", "dark"];
const tokenNames = new Set<string>(colorTokens.map(({ token }) => token));
const paletteIds = new Set<string>(["design", ...colormaps.map(({ id }) => id)]);
const hexColor = /^#[0-9a-fA-F]{6}$/;

function isRecord(value: unknown): value is Record<string, unknown> {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

export function resolveThemeSettings(
    input: unknown,
    options: ThemeResolutionOptions = {},
): ThemeResolution {
    const issues: string[] = [];
    const source = isRecord(input) ? input : {};
    if (input !== undefined && !isRecord(input)) issues.push("Invalid settings object.");
    if (source.version !== undefined && source.version !== 1) {
        return {
            settings: { ...defaultThemeSettings, overrides: { light: {}, dark: {} } },
            issues: ["Unsupported settings version."],
        };
    }
    let design = isDesignModeId(source.design) ? source.design : "basic";
    if (source.design !== undefined && !isDesignModeId(source.design)) {
        issues.push("Unknown design; using Basic.");
    }
    if (!options.allowUnreleased && getDesignMode(design).releaseStatus !== "released") {
        issues.push("Unreleased design; using Basic.");
        design = "basic";
    }
    let definition = getDesignMode(design);
    let appearance: Appearance = source.appearance === "dark" ? "dark"
        : source.appearance === "light" ? "light" : definition.defaultAppearance;
    if (source.appearance !== undefined && !appearances.includes(source.appearance as Appearance)) {
        issues.push("Unknown appearance; using design default.");
    }
    if (design === "dark-ui" && appearance === "light") {
        design = "basic";
        definition = getDesignMode(design);
        issues.push("Dark UI Light resolves to Basic Light.");
    } else if (!definition.appearances.includes(appearance)) {
        appearance = definition.defaultAppearance;
        issues.push("Unsupported appearance; using design default.");
    }
    const fallbackPalette = design === "basic" ? "neutral" : "design";
    let colormap: PaletteId = fallbackPalette;
    if (typeof source.colormap === "string" && paletteIds.has(source.colormap)) {
        colormap = source.colormap as PaletteId;
    } else if (source.colormap !== undefined) {
        issues.push("Unknown colormap; using design default.");
    }
    const overrides: ColorOverrides = { light: {}, dark: {} };
    if (source.overrides !== undefined) {
        if (!isRecord(source.overrides)) {
            issues.push("Invalid color overrides.");
        } else {
            for (const [mode, values] of Object.entries(source.overrides)) {
                if (!appearances.includes(mode as Appearance) || !isRecord(values)) {
                    issues.push(`Invalid override appearance: ${mode}.`);
                    continue;
                }
                for (const [token, value] of Object.entries(values)) {
                    if (!tokenNames.has(token)) {
                        issues.push(`Unknown color token: ${token}.`);
                    } else if (typeof value !== "string" || !hexColor.test(value)) {
                        issues.push(`Invalid hex color: ${mode}.${token}.`);
                    } else {
                        overrides[mode as Appearance][token as ColorToken] = value.toLowerCase();
                    }
                }
            }
        }
    }
    return { settings: { version: 1, design, appearance, colormap, overrides }, issues };
}

function ownedKey(key: string): boolean {
    if (["design", "mode", "colormap"].includes(key)) return true;
    return appearances.some((appearance) => colorTokens.some(
        ({ token }) => key === `${appearance}.${token.slice(2)}`,
    ));
}

export function parseThemeUrl(
    url: URL,
    options: ThemeResolutionOptions = {},
): ThemeResolution {
    const input: Record<string, unknown> = { version: 1 };
    for (const [key, property] of [
        ["design", "design"], ["mode", "appearance"], ["colormap", "colormap"],
    ]) {
        if (url.searchParams.has(key)) input[property] = url.searchParams.get(key);
    }
    const overrides: ColorOverrides = { light: {}, dark: {} };
    for (const appearance of appearances) {
        for (const { token } of colorTokens) {
            const value = url.searchParams.get(`${appearance}.${token.slice(2)}`);
            if (value !== null) overrides[appearance][token] = value;
        }
    }
    input.overrides = overrides;
    const result = resolveThemeSettings(input, options);
    for (const key of new Set(url.searchParams.keys())) {
        if (ownedKey(key) && url.searchParams.getAll(key).length > 1) {
            result.issues.push(`Duplicate theme query: ${key}; using first value.`);
        }
    }
    return result;
}

export function writeThemeUrl(
    url: URL,
    settings: ThemeSettings,
    options: ThemeResolutionOptions = {},
): URL {
    const next = new URL(url.href);
    const value = resolveThemeSettings(settings, options).settings;
    for (const key of [...next.searchParams.keys()]) {
        if (ownedKey(key)) next.searchParams.delete(key);
    }
    if (value.design !== "basic") next.searchParams.set("design", value.design);
    if (value.appearance !== "light") next.searchParams.set("mode", value.appearance);
    const defaultPalette = value.design === "basic" ? "neutral" : "design";
    if (value.colormap !== defaultPalette) next.searchParams.set("colormap", value.colormap);
    for (const appearance of appearances) {
        for (const { token } of colorTokens) {
            const color = value.overrides[appearance][token];
            if (color) next.searchParams.set(`${appearance}.${token.slice(2)}`, color);
        }
    }
    return next;
}

export function resolveThemeTokens(
    settings: ThemeSettings,
    options: ThemeResolutionOptions = {},
): ThemeTokenMap {
    const value = resolveThemeSettings(settings, options).settings;
    const definition = getDesignMode(value.design);
    const tokens: ThemeTokenMap = {
        ...basicShapeTokens,
        ...basicDocumentTokens,
        ...(value.appearance === "dark" ? {
            "--shadow-float": "0 4px 16px rgb(0 0 0 / 20%)",
            "--overlay": "rgb(0 0 0 / 65%)",
        } : {}),
        ...definition.tokens,
    };
    const colors = value.colormap === "design"
        ? definition.palettes[value.appearance]
        : paletteTokens[value.colormap][value.appearance];
    for (const { token } of colorTokens) {
        const paletteToken = `--palette-${token.slice(2)}` as const;
        tokens[paletteToken] = colors[token];
        tokens[token] = value.overrides[value.appearance][token]
            ?? `var(${paletteToken})`;
        const alias = token === "--message-user-background"
            ? "--color-message-user" : `--color-${token.slice(2)}` as const;
        tokens[alias] = `var(${token})`;
    }
    tokens["--radius-sm"] = "var(--radius)";
    tokens["--radius-md"] = value.design === "basic"
        ? "0.375rem" : "var(--radius)";
    tokens["--font-sans"] = "var(--font-ui)";
    tokens["--text-sm"] = "var(--type-body-size)";
    tokens["--text-xs"] = "var(--type-caption-size)";
    return tokens;
}

import { getDesignMode } from "./design-modes";
import {
    resolveThemeSettings, resolveThemeTokens,
    type ThemeResolutionOptions,
} from "./design-mode-settings";

export function applyThemeToElement(
    element: HTMLElement,
    input: unknown,
    options: ThemeResolutionOptions = {},
): () => void {
    const { settings } = resolveThemeSettings(input, options);
    const properties = {
        ...resolveThemeTokens(settings, options),
        "color-scheme": settings.appearance,
        "font-family": "var(--font-ui)",
        "font-size": "var(--type-body-size)",
        "line-height": "var(--type-body-leading)",
        color: "var(--foreground)",
    };
    const attributes = {
        "data-design": settings.design,
        "data-appearance": settings.appearance,
        "data-colormap": settings.colormap,
        "data-recipe": getDesignMode(settings.design).recipe,
    };
    const previousProperties = Object.keys(properties).map((name) => ({
        name, value: element.style.getPropertyValue(name),
        priority: element.style.getPropertyPriority(name),
    }));
    const previousAttributes = Object.keys(attributes).map((name) => ({
        name, value: element.getAttribute(name),
    }));
    const hadDark = element.classList.contains("dark");
    for (const [name, value] of Object.entries(properties)) {
        element.style.setProperty(name, value);
    }
    for (const [name, value] of Object.entries(attributes)) {
        element.setAttribute(name, value);
    }
    element.classList.toggle("dark", settings.appearance === "dark");
    return () => {
        for (const { name, value, priority } of previousProperties) {
            if (value) element.style.setProperty(name, value, priority);
            else element.style.removeProperty(name);
        }
        for (const { name, value } of previousAttributes) {
            if (value === null) element.removeAttribute(name);
            else element.setAttribute(name, value);
        }
        element.classList.toggle("dark", hadDark);
    };
}

import { resolveThemeSettings, type ThemeResolutionOptions } from "./design-mode-settings";
import type { ThemeSettings } from "./design-modes";

export type ThemeMessage = {
    type: "pydemia-ui-theme";
    version: 1;
    revision: number;
    settings: ThemeSettings;
};
export type ThemeAppliedMessage = {
    type: "pydemia-ui-theme-applied";
    version: 1;
    revision: number;
};
export type ThemeInvalidatedMessage = {
    type: "pydemia-ui-theme-invalidated";
    version: 1;
    revision: number;
};

function record(value: unknown): value is Record<string, unknown> {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

function revisionValid(value: unknown): value is number {
    return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

/** Source and origin must be checked by the caller before reading a message. */
export function readThemeMessage(
    data: unknown,
    lastRevision: number,
    options: ThemeResolutionOptions = {},
): ThemeMessage | null {
    if (!record(data) || data.type !== "pydemia-ui-theme" || data.version !== 1 ||
        !revisionValid(data.revision) || data.revision <= lastRevision ||
        !record(data.settings)) return null;
    const settings = data.settings;
    if (settings.version !== 1 || typeof settings.design !== "string" ||
        typeof settings.appearance !== "string" ||
        typeof settings.colormap !== "string" || !record(settings.overrides) ||
        !record(settings.overrides.light) || !record(settings.overrides.dark)) return null;
    const resolved = resolveThemeSettings(settings, options);
    if (resolved.issues.length) return null;
    return {
        type: "pydemia-ui-theme", version: 1,
        revision: data.revision, settings: resolved.settings,
    };
}

export function createThemeMessage(
    settings: ThemeSettings,
    revision: number,
    options: ThemeResolutionOptions = {},
): ThemeMessage {
    const message = readThemeMessage({
        type: "pydemia-ui-theme", version: 1, revision, settings,
    }, -1, options);
    if (!message) throw new TypeError("Invalid theme message settings or revision.");
    return message;
}

export function createThemeAppliedMessage(revision: number): ThemeAppliedMessage {
    if (!revisionValid(revision)) throw new TypeError("Invalid theme revision.");
    return { type: "pydemia-ui-theme-applied", version: 1, revision };
}

/** Only an acknowledgement for the latest sent revision is accepted. */
export function readThemeAppliedMessage(
    data: unknown,
    expectedRevision: number,
): ThemeAppliedMessage | null {
    if (!record(data) || data.type !== "pydemia-ui-theme-applied" ||
        data.version !== 1 || !revisionValid(data.revision) ||
        data.revision !== expectedRevision) return null;
    return createThemeAppliedMessage(data.revision);
}

export function createThemeInvalidatedMessage(revision: number): ThemeInvalidatedMessage {
    if (!revisionValid(revision)) throw new TypeError("Invalid theme revision.");
    return { type: "pydemia-ui-theme-invalidated", version: 1, revision };
}

/** A local change invalidates only the latest sent revision. */
export function readThemeInvalidatedMessage(
    data: unknown,
    expectedRevision: number,
): ThemeInvalidatedMessage | null {
    if (!record(data) || data.type !== "pydemia-ui-theme-invalidated" ||
        data.version !== 1 || !revisionValid(data.revision) ||
        data.revision !== expectedRevision) return null;
    return createThemeInvalidatedMessage(data.revision);
}

import {
    useCallback, useInsertionEffect, useLayoutEffect, useRef, useState,
    type ComponentProps,
} from "react";
import { applyThemeToElement } from "./theme-dom";
import { PortalScope } from "./portal-scope";
import type { ThemeSettings } from "./design-modes";
import type { ThemeResolutionOptions } from "./design-mode-settings";

export type ThemeScopeProps = ComponentProps<"div"> & {
    settings?: Partial<ThemeSettings>;
    options?: ThemeResolutionOptions;
};

export function ThemeScope({
    settings, options, children, ref, ...props
}: ThemeScopeProps) {
    const elementRef = useRef<HTMLDivElement>(null);
    const setElementRef = useCallback((element: HTMLDivElement | null) => {
        elementRef.current = element;
        if (typeof ref === "function") return ref(element);
        if (ref) ref.current = element;
    }, [ref]);
    const [host] = useState(() => {
        if (typeof document === "undefined") return null;
        const portalHost = document.createElement("div");
        portalHost.setAttribute("data-theme-portal", "");
        applyThemeToElement(portalHost, settings, options);
        return portalHost;
    });
    useInsertionEffect(() => {
        if (!host) return;
        host.ownerDocument.body.appendChild(host);
        return () => {
            // Remove after React has detached the portal children in this commit.
            queueMicrotask(() => host.remove());
        };
    }, [host]);
    useLayoutEffect(() => {
        const restoreElement = applyThemeToElement(
            elementRef.current!, settings, options,
        );
        const restoreHost = host
            ? applyThemeToElement(host, settings, options) : undefined;
        return () => {
            restoreElement();
            restoreHost?.();
        };
    }, [host, settings, options, props.className, props.style]);
    return (
        <div {...props} ref={setElementRef}>
            <PortalScope container={host ?? undefined}>
                {children}
            </PortalScope>
        </div>
    );
}

