  --surface-image: none;
  --surface-fill: var(--surface);
  --canvas-image: none;
  --title-fill: var(--surface-subtle);
  --title-ink: var(--muted);
  --component-heading-weight: 600;
  --recipe-panel-columns: initial;
  --recipe-mid-columns: minmax(0, 1fr);
  --recipe-panel-gap: initial;
  --recipe-chart-row: auto;
  --recipe-last-column: auto;
  --recipe-header-margin: 0;
  --recipe-floating-radius: 0;
  --recipe-header-shadow: none;
  --recipe-sidebar-margin: 0;
