:where([data-design]) :where([data-ui="button"]:not([data-variant="ghost"])) {
  border-width: var(--border-width, 1px);
  box-shadow: var(--control-decoration);
}
:where([data-design]) :where([data-ui="input"], [data-ui="textarea"], [data-ui="select-trigger"], [data-ui="native-select"]):not([data-appearance="underline"]) {
  border-width: var(--border-width, 1px);
  box-shadow: var(--field-decoration);
}
:where([data-design]) :where([data-ui="badge"]) {
  border-width: var(--border-width, 1px);
}
:where([data-design]) :where([data-ui="card"][data-variant="default"]) {
  border-width: var(--border-width, 1px);
  box-shadow: var(--card-decoration);
  background-image: var(--surface-image);
  background-color: var(--surface-fill);
  backdrop-filter: var(--surface-filter);
}
:where([data-design]) :where([data-ui="heading"]) {
  font-family: var(--font-heading, var(--font-ui));
  font-weight: var(--component-heading-weight);
