}
:where([data-design]) :where([data-ui="overlay-panel"]):not([data-size="fullscreen"]) {
  border-width: var(--border-width, 1px);
  border-radius: var(--panel-radius, var(--radius));
  background-color: var(--surface-fill);
  background-image: var(--surface-image);
  backdrop-filter: var(--surface-filter);
  box-shadow: var(--panel-shadow, var(--shadow-float));
}
:where([data-design]) :where([data-ui="drawer-panel"]) {
  border-width: var(--border-width, 1px);
